{
  "plans": [
    {
      "id": "P11",
      "type": "true_false",
      "recordIds": ["F11"],
      "intent": "Xác định xem có tồn tại giá trị X nguyên trong khoảng 0‑100° sao cho khi thay vào phương trình đường thẳng qua (0, 32) và (100, 212) cho Y = 300°.",
      "reasoningSteps": [
        "Tính hệ số dốc và phương trình đường thẳng",
        "Giải X cho Y = 300° và kiểm tra X có phải là số nguyên trong [0,100] hay không"
      ],
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "credibleDistractors": null,
      "reasoningJustification": "Yêu cầu kiểm tra tính nguyên của X tạo ra ràng buộc ngược và quyết định nhị phân, vượt qua việc chỉ thay thế đơn giản.",
      "evidence": [
        {
          "chunkId": "b6b8a1ad-f19a-4496-9481-dc50420dee41",
          "quote": "Đườ ng thẳng đi qua điểm (0; 32) và (100; 212), kéo dài lê n phả i."
        }
      ]
    },
    {
      "id": "P12",
      "type": "short_answer",
      "recordIds": ["F12"],
      "intent": "Cho p₁ = 5 atm, V₁ = 10 L, T₁ = 300 K, V₂ = 2 L. Tìm nhiệt độ tối đa T₂ (K) sao cho áp suất cuối cùng p₂ không vượt quá 12 atm và T₂ ≥ 1,5 × T₁.",
      "reasoningSteps": [
        "Áp dụng định luật khí hỗn hợp (p₁·V₁)/T₁ = (p₂·V₂)/T₂",
        "Đặt p₂ = 12 atm và T₂ ≥ 1,5 T₁, giải bất phương trình để tìm giá trị lớn nhất của T₂"
      ],
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "credibleDistractors": null,
      "reasoningJustification": "Kết hợp bất phương trình về áp suất và ràng buộc tỷ lệ nhiệt độ tạo ra suy luận phụ thuộc phức tạp, không chỉ là thay thế công thức.",
      "evidence": [
        {
          "chunkId": "f247b106-b908-411e-b7b6-a9928e6b9305",
          "quote": "Câu 12: Môt lựong khi lí tươ ng xac đinh ỏ trạtn thài có á suât p1, the tich V1, nhiêt đọ T1 thuc hiên mot quâ trinh bién đỗi trạtn thài đên trạtn thài có á suât p2, the tich V2, nhiêt đọ T2. Phuong trinh thuc dung?"
        }
      ]
    },
    {
      "id": "P13",
      "type": "multiple_choice",
      "recordIds": ["F14", "F15"],
      "intent": "Khi 1 g băng ở 0 °C được cho vào 1 g nước ở 40 °C (không xét nhiệt dung của bình), xác định đúng nhất về trạng thái cân bằng cuối cùng: (A) toàn bộ băng tan, nhiệt độ cuối cùng >0 °C; (B) một phần băng tan, nhiệt độ cuối cùng =0 °C; (C) một phần nước đông lại, nhiệt độ cuối cùng <0 °C; (D) không có thay đổi nào.",
      "reasoningSteps": [
        "Tính nhiệt lượng Q_water do nước nguội tới 0 °C",
        "So sánh Q_water với Q_melt = m_ice·L_f để xác định nếu Q_water < Q_melt thì không đủ để tan hết băng",
        "Nếu Q_water < Q_melt, tính lượng băng tan và xác định rằng phần nước còn lại sẽ làm nhiệt độ cuối cùng duy trì ở 0 °C",
        "Nếu Q_water > Q_melt, tính nhiệt dư và kiểm tra khả năng làm lạnh nước còn lại dưới 0 °C (đông lại)"
      ],
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "credibleDistractors": true,
      "reasoningJustification": "Yêu cầu đánh giá cả khả năng tan hết băng và khả năng nước đông lại, đòi hỏi suy luận ngược và so sánh ngưỡng năng lượng, vượt qua tính toán đơn giản.",
      "evidence": [
        {
          "chunkId": "679573f7-34b7-49aa-9e92-523f1835d076",
          "quote": "Câu 16: Đưa 1 g nước đá được ở 0°C được vào một nhiệt lượng kế chứa 1 g nước ở 40°C. Bỏ qua nhiệt dung của nhiệt lượng kế. Biết nhiệt nóng chảy riêng của nước đá là 3,36.10⁵ J/kg và nhiệt dung riêng của nước là 4200 J/kg.K."
        },
        {
          "chunkId": "67e92431-60e9-4666-bb57-78a286b28079",
          "quote": "nóng chảy riêng của nước đá là 3,36.10⁵ J/kg và nhiệt dung riêng của nước là 4200 J/kg.K. Trạng thái cân bằng của hệ gồm"
        }
      ]
    },
    {
      "id": "P14",
      "type": "selection",
      "recordIds": ["F15", "F14"],
      "intent": "Chọn các phát biểu đúng về trạng thái cân bằng của hệ gồm 1 g băng 0 °C và 1 g nước 40 °C (không xét nhiệt dung của bình):\n1. Nhiệt độ cuối cùng là 0 °C.\n2. Lượng băng tan bằng Q_water/L_f.\n3. Nếu Q_water < Q_melt thì một phần nước sẽ đông lại.\n4. Khi Q_water > Q_melt, nhiệt độ cuối cùng sẽ cao hơn 0 °C.",
      "reasoningSteps": [
        "Sử dụng cân bằng năng lượng Q_water = Q_melt để xác định lượng băng tan",
        "Kiểm tra điều kiện Q_water <, =, > Q_melt để đưa ra các kết luận về nhiệt độ và trạng thái",
        "Đánh giá từng phát biểu dựa trên kết quả trên"
      ],
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "credibleDistractors": true,
      "reasoningJustification": "Yêu cầu người học phải phân tích ba trường hợp năng lượng khác nhau và đưa ra quyết định cho từng phát biểu, tạo ra suy luận phụ thuộc và so sánh ngưỡng.",
      "evidence": [
        {
          "chunkId": "67e92431-60e9-4666-bb57-78a286b28079",
          "quote": "nóng chảy riêng của nước đá là 3,36.10⁵ J/kg và nhiệt dung riêng của nước là 4200 J/kg.K. Trạng thái cân bằng của hệ gồm"
        },
        {
          "chunkId": "679573f7-34b7-49aa-9e92-523f1835d076",
          "quote": "Câu 16: Đưa 1 g nước đá được ở 0°C được vào một nhiệt lượng kế chứa 1 g nước ở 40°C. Bỏ qua nhiệt dung của nhiệt lượng kế."
        }
      ]
    },
    {
      "id": "P15",
      "type": "true_false",
      "recordIds": ["F16"],
      "intent": "Phát biểu \"Trong chu trình tủ lạnh, nếu hệ số COP = 3 và công nén A = 180 kJ, thì nhiệt lượng Q₂ mà môi chất làm lạnh thải ra môi trường luôn bằng 720 kJ\" là đúng.",
      "reasoningSteps": [
        "Tính Q₁ = COP·A = 3 × 180 kJ = 540 kJ",
        "Sử dụng định luật năng lượng Q₂ = Q₁ + A để suy ra Q₂ = 720 kJ",
        "Xem xét giả thiết rằng COP được xác định tại cùng điều kiện hoạt động với A = 180 kJ; nếu COP là giá trị trung bình, phát biểu có thể sai"
      ],
      "selfContained": true,
      "sourceSupported": true,
      "hardReasoning": true,
      "credibleDistractors": null,
      "reasoningJustification": "Yêu cầu người học phải nhận ra rằng tính đúng/sai phụ thuộc vào việc COP được định nghĩa ở cùng điều kiện, tạo ra suy luận ngược và quyết định dựa trên giả thiết.",
      "evidence": [
        {
          "chunkId": "67e92431-60e9-4666-bb57-78a286b28079",
          "quote": "Hệ số làm lạnh của tủ lạnh COP là tỉ số Q₁/A. Một tủ lạnh loại vừa có hệ số làm lạnh COP = 3. Trong một chu trình, môi chất làm lạnh nhận công A=180kJ từ máy nén, nhiệt lượng Q₂ mà môi chất làm lạnh thải ra môi trường ở dàn nóng là"
        }
      ]
    }
  ]
}
